function Cup() {}
Cup.prototype.size = "small";

const first = new Cup();

Cup.prototype.size = "medium";
Cup.prototype = { size: "large" };

const second = new Cup();
Cup.prototype.size = "huge";

console.log(first.size, second.size);
console.log(first.constructor === Cup, second.constructor === Cup);
console.log(Object.getPrototypeOf(second) === Cup.prototype);
